CR="Foto: prensa chilena (ver descripción)"
def cita(et,fr,at="",fin=""): return ("mod","cita",1,dict(etiqueta=et,frase=fr,atribucion=at,fin=fin))
def cont(items): return ("mod","contadores",1,dict(items=items,cortos=[i[1].split(' ')[0] for i in items]))
def vers(t,a,b,pie=""): return ("mod","versiones",1,dict(titulo=t,a=a,b=b,pie=pie))
def cap(n,t,d): return ("cap",None,0,dict(k=f"CAPÍTULO {n}",t=t,d=d))
def px(q,w=1,txt=None): return ("px",q,w,dict(txt=txt))
def foto(f,w=1,txt=None): return ("foto",f,w,dict(txt=txt))
def mod(m,w=1,**d): return ("mod",m,w,d)
def tl(t,ev): return mod("timeline",titulo=t,eventos=ev)
def evi(t,items): return mod("evidencia",titulo=t,items=items)
